import type { ArcRotateCamera, SceneContext } from "@babylonjs/lite";
import { attachControl } from "@babylonjs/lite";

export function attachFastOrbit(
  camera: ArcRotateCamera,
  canvas: HTMLCanvasElement,
  scene: SceneContext
): () => void {
  const originalAngularSensibility = camera.angularSensibility;
  camera.angularSensibility = originalAngularSensibility * 2;

  const detachControl = attachControl(camera, canvas, scene, { keyboard: false });

  return () => {
    try {
      detachControl();
    } finally {
      camera.angularSensibility = originalAngularSensibility;
    }
  };
}
```

I wrapped the library’s standard `attachControl` and doubled `camera.angularSensibility` while attached, so rotate drag and its inertial glide use twice the default angular sensitivity while wheel zoom remains unchanged. I was assuming `attachControl` is exported from the package root and that it uses `camera.angularSensibility` for rotate drag/glide; if the actual export path differs, only the import would need to change.

